// ── Cálculo de desvio de prazo ────────────────────────────────────────────────
function calcDesvio(dataTermino: string | null) {
  if (!dataTermino) return null;
  const hoje = new Date();
  const fim  = new Date(dataTermino);
  const dias = Math.round((fim.getTime() - hoje.getTime()) / 86400000);
  return dias;
}

// Rev. 1811 — `pvPonderadoPorAtividade` (PREVISTO físico, curva S por
// atividade) está em `shared/diasUteis.ts` para ser FONTE ÚNICA também na
// ProgramacaoSemanalLotus e demais consumidores. Ver ali a documentação
// completa (PMI Practice Standard for Scheduling §6.2 / Mattos / Vargas).

// ── Formata data ISO → dd/mm/aaaa ────────────────────────────────────────────
function fmtBR(iso: string | null | undefined): string {
  if (!iso) return "—";
  const m = iso.match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? `${m[3]}/${m[2]}/${m[1]}` : iso;
}

// ── Rev. 1854 — Formata TIMESTAMP (Date|string) → dd/mm/aaaa iOS-safe ─────
// Aceita Date object (drizzle/superjson) OU string vinda crua do Postgres
// ("2026-05-15 21:46:00.123") OU ISO completo ("2026-05-15T21:46:00.123Z").
// iOS Safari rejeita `new Date("2026-05-15 21:46:00")` (espaço em vez de T)
// com "The string did not match the expected pattern" — substitui o espaço
// por T e cai no parser ISO. Patch defensivo (igual Rev. 1849 fez na coluna
// "Tempo de casa" do Equipe).
function fmtTimestampBR(v: string | Date | null | undefined): string {
  if (!v) return "—";
  try {
    if (v instanceof Date) {
      if (isNaN(v.getTime())) return "—";
      return v.toLocaleDateString("pt-BR");
    }
    const s = String(v).trim();
    if (!s) return "—";
    // Caminho rápido: já vem como YYYY-MM-DD (date column) → reusa fmtBR.
    const mDate = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (mDate) return `${mDate[3]}/${mDate[2]}/${mDate[1]}`;
    // Normaliza Postgres "YYYY-MM-DD HH:MM:SS[.fff][+TZ]" → ISO com T.
    const iso = s.replace(" ", "T");
    const d = new Date(iso);
    if (isNaN(d.getTime())) {
      // Último fallback: extrai só a data se houver.
      const mAny = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
      return mAny ? `${mAny[3]}/${mAny[2]}/${mAny[1]}` : "—";
    }
    return d.toLocaleDateString("pt-BR");
  } catch {
    return "—";
  }
}

// ── Semana (segunda-feira) ────────────────────────────────────────────────────
function toMonday(d: Date) {
  const day = d.getDay();
  const diff = (day === 0 ? -6 : 1 - day);
  const m = new Date(d.getTime() + diff * 86400000);
  return m.toISOString().split("T")[0];
}

// ── Rev. 2244 — `todayLocalISO()`: data de hoje em YYYY-MM-DD no fuso LOCAL ──
// Substitui `new Date().toISOString().split("T")[0]` (que retorna UTC) em
// TODO o arquivo. Bug observado em VITRA (cutoff=Qui): às 21h BRT de quinta
// 21/05, `toISOString` retornava "2026-05-22" (já 00h UTC do dia seguinte)
// → "ATUAL" passava pra próxima semana cutoff (22-28/05) ANTES da virada
// real do dia. Mesmo problema podia afetar `dataNecessaria`, `dataRevisao`,
// `semana`, marcação de atrasos, posição da linha vermelha no Gantt.
function todayLocalISO(): string {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${dd}`;
}

// ── Rev. 1667 — Camada de tradução Cutoff↔Monday ─────────────────────────────
// O banco continua armazenando `planejamento_avancos.semana` como Segunda-feira
// (compatibilidade com Curva S, REFIS, Portal, EVM, Medição etc.). Mas a UI
// passa a EXIBIR semanas alinhadas ao cutoff oficial do projeto (PMBOK Status
// Date / Last Planner). Para cutoff=Quinta(4), as semanas são Sex→Qui — igual
// à Programação Semanal. A conversão é 1:1 porque cada janela de 7 dias contém
// exatamente UMA Segunda. Assim, "Sem 1 (01/05–07/05)" mapeia internamente
// para Mon 04/05 que é o que vai pro banco.
//
// Funções:
//   • mondayOfCutoffWeek(dateISO, cutoffDow): Monday DENTRO da semana-cutoff
//     que contém dateISO. Usado para chave de storage / state.
//   • cutoffWeekFromMonday(mondayISO, cutoffDow): { ini, fim } da semana
//     visível (Sex→Qui para cutoff=Qui). Usado para labels e ranges visuais.
function mondayOfCutoffWeek(dateISO: string, cutoffDow: number): string {
  const startDow = (cutoffDow + 1) % 7;       // dia inicial da semana cutoff
  const d = new Date(dateISO + "T12:00:00");
  const back = (d.getDay() - startDow + 7) % 7;
  const start = new Date(d.getTime() - back * 86400000);   // primeiro dia da semana cutoff
  const startToMon = (1 - startDow + 7) % 7;               // offset até a Segunda interna
  const mon = new Date(start.getTime() + startToMon * 86400000);
  return mon.toISOString().split("T")[0];
}
function cutoffWeekFromMonday(mondayISO: string, cutoffDow: number): { ini: string; fim: string } {
  const startDow = (cutoffDow + 1) % 7;
  const d = new Date(mondayISO + "T12:00:00");
  const back = (1 - startDow + 7) % 7;
  const ini = new Date(d.getTime() - back * 86400000);
  const fim = new Date(ini.getTime() + 6 * 86400000);
  return { ini: ini.toISOString().split("T")[0], fim: fim.toISOString().split("T")[0] };
}
function ultimasSemanas(n: number) {
  const semanas: string[] = [];
  const hoje = new Date();
  for (let i = n - 1; i >= 0; i--) {
    const d = new Date(hoje.getTime() - i * 7 * 86400000);
    semanas.push(toMonday(d));
  }
  return [...new Set(semanas)];
}
function semanasRange(from: string | null | undefined, to: string | null | undefined): string[] {
  const hoje = new Date();
  const start = from ? new Date(from + "T12:00:00") : new Date(hoje.getTime() - 12 * 7 * 86400000);
  const end   = to   ? new Date(to   + "T12:00:00") : hoje;
  const weeks: string[] = [];
  let curr = new Date(toMonday(start) + "T12:00:00");
  const last = new Date(toMonday(end) + "T12:00:00");
  while (curr <= last) {
    weeks.push(toMonday(curr));
    curr = new Date(curr.getTime() + 7 * 86400000);
  }
  return [...new Set(weeks)];
}

function labelSemana(s: string, idx: number, cutoffDow: number = 4) {
  // Rev. 1667 — Mostra a semana cutoff-alinhada (Sex→Qui para cutoff=Qui).
  const { ini: iniStr, fim: fimStr } = cutoffWeekFromMonday(s, cutoffDow);
  const br = (iso: string) => iso.split("-").reverse().join("/");
  return `${idx + 1}ª Semana — ${br(iniStr)} até ${br(fimStr)}`;
}
function isCurrentWeek(s: string, cutoffDow: number = 4): boolean {
  // Rev. 1667 — "Atual" agora é a semana cutoff que contém hoje, não Mon-Sun.
  const today = todayLocalISO();
  const { ini, fim } = cutoffWeekFromMonday(s, cutoffDow);
  return today >= ini && today <= fim;
}

